contracts/core/ArbitrageCore.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IArbitrage.sol";
import "../interfaces/IArbitrageVault.sol";
import "../interfaces/ISpotArbitrage.sol";
import "../interfaces/IFlashLoan.sol";
import "../interfaces/IConfigManager.sol";

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

contract ArbitrageCore is UUPSUpgradeable, OwnableUpgradeable, ReentrancyGuardUpgradeable {

    /**
    *套利调度核心合约
    *调用套利策略执行
    *验证获利
    *分润：暂定平台收取10%（即应配置100），此值放置在configManager中进行管理，以便管理员随时调整
    */

    

    ISpotArbitrage public spotArbitrage;
    IFlashLoanSimpleReceiver public flashLoanArbitrage;
    IConfigManager public configManager;    //参数管理   平台收取利润的10%作为服务费等
         
    address public spotArbImp;              // 实现套利(实现IArbitrage.sol)
    address public platFormWallet;
    address public backCaller;              //后端
    address[] public supportAssets;


    //金库地址
    mapping(address => IArbitrageVault) public vaults;

    //事件：金库资产套利
    event VaultArbitrageExecuted(
        address indexed vault,
        address indexed asset,
        uint256 amountIn,
        uint256 profit,
        uint256 platFormFee,//平台服务费
        uint256 netProfitToVault,//转入金库的净收益（刨除平台服务费）
        uint256 timestamp
    );

    //事件：闪电贷套利
    event FlashLoanArbitrageExecuted(
        address indexed initiator,
        address indexed asset,
        address tokenIn,
        uint256 amountIn,
        uint256 profit,
        uint256 timestamp
    );

    event VaultAdd(address indexed asset, address indexed vault);

    modifier onlybackCaller() {
        require(msg.sender == backCaller || msg.sender == owner(), "Only back or owner can call");
        _;
    }

    constructor () {
        _disableInitializers();
    }

    function initialize(
        address _spotArbitrage,
        address _flashLoanArbitrage,
        address _platFormWallet,
        address _configManager,
        address _backCaller
    ) public initializer {
        __Ownable_init(msg.sender);
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();

        require(_spotArbitrage != address(0), "Invalid spot Arbitrage");
        require(_flashLoanArbitrage != address(0), "Invalid flashLoan Arbitrage");
        require(_platFormWallet != address(0), "Invalid platForm Wallet");
        require(_configManager != address(0), "Invalid config Manager");
        require(_backCaller != address(0), "Invalid backend Caller");

        spotArbitrage = ISpotArbitrage(_spotArbitrage);
        flashLoanArbitrage = IFlashLoanSimpleReceiver(_flashLoanArbitrage);
        platFormWallet = _platFormWallet; //利润转账地址(项目方钱包地址)
        configManager = IConfigManager(_configManager);
        backCaller = _backCaller;


    }

    //金库函数：添加金库
    function addVault(
        address asset,
        address vault
    ) external onlyOwner {
        require(asset != address(0), "Invalid asset");
        require(vault != address(0), "Invalid vault");
        require(address(vaults[asset]) == address(0), "vault already exists" );

        vaults[asset] = IArbitrageVault(vault);
        supportAssets.push(asset);

        emit VaultAdd(asset, vault);
    }

    //金库函数：获取金库信息
    function getVaultInfo(
        address asset
    )external view returns (
        address vaultAddress,
        uint256 totalAssets,
        uint256 availableAssets
    ) {
        IArbitrageVault vault = vaults[asset];
        require(address(vault) != address(0), "vault not exists");

        return (
            address(vault),
            vault.totalAssets(),
            vault.getAvailableForArbitrage()
        );
    }

    //核心函数：实现套利的调用，并对盈利&分润计算
    /**
    *入参：
    *原代币(输入)，
    *兑换代币（输出），注意输入的代币要和输出的代币相同，以便比较收益，路径如：ETH-USDT-ETH
    *购买数量（输入数量），
    *交易路径(USDC,WETH,DAI,USDC三角套利后续扩展，当前先完成单点套利：ETH-USDT-ETH)，
    *dex地址：在dex集成路由中
    *
    *自有资金套利&闪电贷套利，两种套利模式对象不同，前者取自金库，可多人打包进行，后者针对用户，闪电贷不可跨用户
    *
    */
    //枚举套利方案：自有资产（金库），闪电贷
    enum StrategyTypes {
        OWN_FUNDS, 
        FLASH_LOAN
    }
    

    function executeStrategy(
        StrategyTypes strategyTypes,
        IArbitrage.ArbitrageParams calldata params
    ) external onlybackCaller nonReentrant {
        if (strategyTypes == StrategyTypes.OWN_FUNDS ) {
            _executedVaultArbitrage(params);
        } else if (strategyTypes == StrategyTypes.FLASH_LOAN) {
            _executedFlashLoanArbitrage(params);
        }
    }


    function _executedVaultArbitrage(
        IArbitrage.ArbitrageParams calldata params
    ) private {
        address asset = params.asset;
        uint256 amountIn = params.amountIn;
        address[] calldata swapPath = params.swapPath;
        address[] calldata dexes = params.dexes;
        uint256 minProfit = params.minProfit;

        //参数验证
        require(amountIn > 0, "amountIn > 0");
        require(swapPath.length >= 3, "swapPath need 3 at least");
        require(dexes.length == swapPath.length - 1, "dexes = swapPath -1");
        require(swapPath[0] == asset, "swapPath[0] is tokenIn");
        require(asset == swapPath[swapPath.length - 1], "tokenIn = tokenOut");

        //获取vault,查询可用资金
        IArbitrageVault vault = vaults[asset];
        require(address(vault) != address(0), "vault not exists");

        uint256 availableVault = vault.getAvailableForArbitrage();
        require(amountIn <= availableVault, "amountIn too much");

        //获取vault资金授权
        vault.approveForArbitrage(amountIn);

        //资金转入本合约
        ERC20Upgradeable(asset).transferFrom(address(vault), address(this), amountIn);

        //记录套利前余额
        uint256 balanceBefore = ERC20Upgradeable(asset).balanceOf(address(this));
        //授权给套利实现合约
        ERC20Upgradeable(asset).approve(address(spotArbitrage), amountIn);
        //执行套利策略
        spotArbitrage.executeSwaps(
            asset,
            swapPath[swapPath.length - 1],
            amountIn,
            swapPath,
            dexes,
            minProfit
        );
        //记录套路后余额
        uint256 balanceAfter = ERC20Upgradeable(asset).balanceOf(address(this));
        
        //计算利润，分成（注意验证minProfit）
        uint256 actProfit = balanceAfter - balanceBefore;
        require(actProfit > minProfit, "Profit below minimum");

        uint256 platFormFee = actProfit * configManager.profitShareFee() / 10000;
        uint256 netProfitToVault = actProfit - platFormFee;

        //将净利润返回vault
        require(balanceAfter >= amountIn + netProfitToVault, "Insufficient  balanceAfter");
        ERC20Upgradeable(asset).transfer(address(vault), amountIn + netProfitToVault);
        ERC20Upgradeable(asset).transfer(platFormWallet, platFormFee);

        //通知金库记录盈利
        vault.recordProfit(netProfitToVault);

        //事件触发VaultArbitrageExecuted
        emit VaultArbitrageExecuted(
            address(vault),
            asset,
            amountIn,
            actProfit,
            platFormFee,
            netProfitToVault,
            block.timestamp
        );
    }

    //闪电贷套利
    function _executedFlashLoanArbitrage(IArbitrage.ArbitrageParams calldata params) private {
        revert("Flash Loan not implemented yet");
        //验证

        //调用闪电贷套利执行

        //事件触发FlashLoanArbitrageExecuted
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner{
        require(newImplementation != address(0), "New implementation is zero address");
    }

}

contracts/core/ArbitrageVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IConfigManager.sol";
import "../interfaces/IArbitrageVault.sol";

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title ArbitrageVault
 * @dev 基于ERC4626标准的套利金库
 * 
 * 核心机制：
 * - 用户存入资产（如WETH）→ 获得份额代币（如arbWETH）
 * - 平台使用池中资金进行套利
 * - 套利利润自动反映在份额价值上
 * - 用户赎回时获得本金 + 收益
 */
contract ArbitrageVault is IArbitrageVault, ERC20, ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;

    // ========== 状态变量 ==========
    IERC20 public immutable asset;           // 底层资产（如WETH）
    address public arbitrageCore;             // 套利调度合约
    
    // 费用设置  改为可插拔，在接口合约中配置
    uint256 public depositFee;
    uint256 public withdrawFee;
    uint256 public performanceFee;
    uint256 public constant DEFAULT_DEPOSITFEE = 0;            // 存款费（basis points）
    uint256 public constant DEFAULT_WITHDRAWFEE = 1;           // 提款费（basis points） 暂定0.01%
    uint256 public constant DEFAULT_PERFORMANCEFEE = 1000;     // 业绩费10%（从利润中收取）
    IConfigManager public configManager;
    
    // 统计数据
    uint256 public totalProfitGenerated;      // 总产生利润
    uint256 public totalFeesCollected;        // 总收取费用
    uint256 public lastArbitrageTime;         // 上次套利时间
    
    // 安全限制
    uint256 public maxTotalAssets;            // 最大总资产
    uint256 public minDepositAmount;          // 最小存款金额
    bool public paused;                       // 暂停状态
    
    //用户地址=>存款记录数组
    mapping(address => IArbitrageVault.DepositRecord[]) public userDeposits;
    //用户存入本金总计
    mapping(address => uint256) public userTotalDeposited;
    //用户提现总计
    mapping(address => uint256) public userTotalWithdraw;

    // ========== 事件 ==========
    
    event Deposit(
        address indexed sender,
        address indexed owner,
        uint256 assets,
        uint256 shares
    );
    
    event Withdraw(
        address indexed sender,
        address indexed receiver,
        address indexed owner,
        uint256 assets,
        uint256 shares
    );
    
    event ArbitrageProfit(
        uint256 profit,
        uint256 fee,
        uint256 timestamp
    );
    
    event ArbitrageLoss(
        uint256 loss,
        uint256 timestamp
    );
    
    // ========== 修饰符 ==========
    
    modifier whenNotPaused() {
        require(!paused, "Vault is paused");
        _;
    }
    
    modifier onlyArbitrageCore() {
        require(msg.sender == arbitrageCore, "Only ArbitrageCore");
        _;
    }
    
    // ========== 构造函数 ==========
    
    /**
     * @param _asset 底层资产地址（如WETH）
     * @param _name 份额代币名称（如"Arbitrage WETH"）
     * @param _symbol 份额代币符号（如"arbWETH"）
     */
    constructor(
        address _asset,
        address _configManager,
        string memory _name,
        string memory _symbol
    ) ERC20(_name, _symbol) Ownable(msg.sender) ReentrancyGuard() {
        require(_asset != address(0), "Invalid asset");
        require(_configManager != address(0), "Invalid config Manager");
        asset = IERC20(_asset);
        maxTotalAssets = type(uint256).max;
        minDepositAmount = 0;
        configManager = IConfigManager(_configManager);
    }
    

    //可插拔关键 支持替换配置
    function setConfigManager(address _newConfigManager) external onlyOwner {
        require(_newConfigManager != address(0), "Invalid new config Manager");
        configManager = IConfigManager(_newConfigManager);
    }


    // ========== ERC4626 核心函数 ==========
    
    /**
     * @dev 返回金库管理的底层资产地址
     */
    function assetAddress() public view override returns (address) {
        return address(asset);
    }
    
    /**
     * @dev 返回金库中的总资产数量
     * 
     * 这是ERC4626的核心函数！
     * 份额价值 = totalAssets() / totalSupply()
     */
    function totalAssets() public view override returns (uint256) {
        return asset.balanceOf(address(this));
    }
    
    /**
     * @dev 将资产数量转换为份额数量
     * 
     * 公式：shares = assets * totalSupply / totalAssets
     * 
     * 示例：
     * - 金库有100 ETH，总份额100
     * - 存入10 ETH
     * - 获得份额 = 10 * 100 / 100 = 10 shares
     */
    function convertToShares(uint256 assets) public view returns (uint256) {
        uint256 supply = totalSupply();
        if (supply == 0) {
            return assets; // 1:1 初始比例
        }
        return (assets * supply) / totalAssets();
    }
    
    /**
     * @dev 将份额数量转换为资产数量
     * 
     * 公式：assets = shares * totalAssets / totalSupply
     * 
     * 示例：
     * - 金库有110 ETH，总份额100（套利赚了10 ETH）
     * - 持有10 shares
     * - 可赎回 = 10 * 110 / 100 = 11 ETH
     */
    function convertToAssets(uint256 shares) public view returns (uint256) {
        uint256 supply = totalSupply();
        if (supply == 0) {
            return shares;
        }
        return (shares * totalAssets()) / supply;
    }
    
    /**
     * @dev 预览存款将获得的份额
     */
    function previewDeposit(uint256 assets) public view returns (uint256) {
        uint256 dePositFee = configManager.getDepositFee(address(this));
        uint256 fee = (assets * dePositFee) / 10000;
        return convertToShares(assets - fee);
    }
    
    /**
     * @dev 预览赎回份额将获得的资产
     */
    function previewRedeem(uint256 shares) public view returns (uint256) {
        uint256 assets = convertToAssets(shares);
        uint256 withDrawFee = configManager.getWithDrawFee(address(this));
        uint256 fee = (assets * withDrawFee) / 10000;
        return assets - fee;
    }
    
    /**
     * @dev 存款：用户存入资产，获得份额
     * 
     * @param assets 存入的资产数量
     * @param receiver 份额接收者
     * @return shares 获得的份额数量
     */
    function deposit(
        uint256 assets,
        address receiver
    ) public nonReentrant whenNotPaused returns (uint256 shares) {
        require(assets > 0, "Cannot deposit 0");
        require(assets >= minDepositAmount, "Below minimum deposit");
        require(
            totalAssets() + assets <= maxTotalAssets,
            "Exceeds max total assets"
        );
        
        // 计算份额（扣除存款费后）
        uint256 dePositFee = configManager.getDepositFee(address(this));
        uint256 fee = (assets * dePositFee) / 10000;
        uint256 assetsAfterFee = assets - fee;
        shares = convertToShares(assetsAfterFee);
        
        //记录用户存金
        userDeposits[receiver].push(IArbitrageVault.DepositRecord({
            amount: assets,
            shares: shares,
            sharesPrice: sharePrice(),
            timestamp: block.timestamp
        }));

        userTotalDeposited[receiver] += assets;
        
        require(shares > 0, "Zero shares");
        
        // 转入资产
        asset.safeTransferFrom(msg.sender, address(this), assets);

        
        // 铸造份额代币给接收者
        _mint(receiver, shares);
        
        // 记录费用
        if (fee > 0) {
            totalFeesCollected += fee;
        }
        
        emit Deposit(msg.sender, receiver, assets, shares);
        
        return shares;
    }
    
    /**
     * @dev 赎回：用户销毁份额，取回资产
     * 
     * @param shares 要赎回的份额数量
     * @param receiver 资产接收者
     * @param owner 份额所有者
     * @return assets 获得的资产数量
     */
    function redeem(
        uint256 shares,
        address receiver,
        address owner
    ) public nonReentrant returns (uint256 assets) {
        require(shares > 0, "Cannot redeem 0");
        require(balanceOf(owner) >= shares, "Insufficient shares");
        
        // 如果调用者不是owner，检查授权
        if (msg.sender != owner) {
            uint256 allowed = allowance(owner, msg.sender);
            require(allowed >= shares, "Insufficient allowance");
            _approve(owner, msg.sender, allowed - shares);
        }
        
        // 计算可获得的资产
        assets = convertToAssets(shares);
        
        // 扣除提款费
        uint256 withDrawFee = configManager.getWithDrawFee(address(this));
        uint256 fee = (assets * withDrawFee) / 10000;
        uint256 assetsAfterFee = assets - fee;
        
        require(assetsAfterFee > 0, "Zero assets");
        require(
            asset.balanceOf(address(this)) >= assetsAfterFee,
            "Insufficient vault balance"
        );
        
        //记录用户提现
        userTotalWithdraw[owner] += assetsAfterFee;

        // 销毁份额代币
        _burn(owner, shares);
        
        // 转出资产
        asset.safeTransfer(receiver, assetsAfterFee);
        
        // 记录费用
        if (fee > 0) {
            totalFeesCollected += fee;
        }
        
        emit Withdraw(msg.sender, receiver, owner, assetsAfterFee, shares);
        
        return assetsAfterFee;
    }
    
    /**
     * @dev 便捷函数：按资产数量提款
     */
    function withdraw(
        uint256 assets,
        address receiver,
        address owner
    ) public returns (uint256 shares) {
        shares = convertToShares(assets);
        redeem(shares, receiver, owner);
        return shares;
    }
    
    // ========== 套利相关函数 ==========
    
    /**
     * @dev 获取可用于套利的资金
     * 
     * 注意：可以设置保留比例，不把全部资金用于套利
     */
    function getAvailableForArbitrage() public view override returns (uint256) {
        uint256 total = totalAssets();
        // 保留10%作为流动性，90%可用于套利
        return (total * 9000) / 10000;
    }
    
    /**
     * @dev 为套利授权资金（由ArbitrageCore调用）
     * 
     * @param amount 授权金额
     */
    function approveForArbitrage(uint256 amount) external onlyArbitrageCore override {
        require(amount <= getAvailableForArbitrage(), "Exceeds available");
        asset.approve(arbitrageCore, amount);
    }
    
    /**
     * @dev 记录套利利润（由ArbitrageCore调用）
     * 
     * 利润自动反映在totalAssets()中
     * 份额持有者自动享受增值
     * 
     * @param profit 本次套利利润
     */
    function recordProfit(uint256 profit) external onlyArbitrageCore override {
        // 收取业绩费
        uint256 perFormanceFee = configManager.getPlatFormFee(address(this));
        uint256 fee = (profit * perFormanceFee) / 10000;
        
        totalProfitGenerated += profit;
        totalFeesCollected += fee;
        lastArbitrageTime = block.timestamp;
        
        // 将费用转给平台
        if (fee > 0) {
            asset.safeTransfer(owner(), fee);
        }
        
        emit ArbitrageProfit(profit, fee, block.timestamp);
    }
    
    /**
     * @dev 记录套利亏损（理论上不应该发生，有minProfit保护）
     */
    function recordLoss(uint256 loss) external onlyArbitrageCore override {
        emit ArbitrageLoss(loss, block.timestamp);
    }
    
    // ========== 查询函数 ==========

     /**
     * @dev 1211新增：获取用户本金
     */
    function getUserBalance(address user) public view returns (uint256) {
        return userTotalDeposited[user];
    }
    
    /**
     * @dev 获取用户的份额余额
     */
    function sharesOf(address user) public view returns (uint256) {
        return balanceOf(user);
    }
    
    /**
     * @dev 获取用户份额对应的资产价值
     */
    function assetsOf(address user) public view returns (uint256) {
        return convertToAssets(balanceOf(user));
    }
    
    /**
     * @dev 获取当前份额价格（每份额值多少资产）
     */
    function sharePrice() public view returns (uint256) {
        uint256 supply = totalSupply();
        if (supply == 0) {
            return 1e18; // 初始价格1:1
        }
        return (totalAssets() * 1e18) / supply;
    }
    
    /**
     * @dev 获取金库统计信息
     */
    function getVaultStats() public view returns (
        uint256 _totalAssets,
        uint256 _totalSupply,
        uint256 _sharePrice,
        uint256 _totalProfit,
        uint256 _totalFees,
        uint256 _lastArbitrageTime
    ) {
        return (
            totalAssets(),
            totalSupply(),
            sharePrice(),
            totalProfitGenerated,
            totalFeesCollected,
            lastArbitrageTime
        );
    }
    
    // ========== 管理函数 ==========
    
    function setArbitrageCore(address _arbitrageCore) external onlyOwner {
        require(_arbitrageCore != address(0), "Invalid address");
        arbitrageCore = _arbitrageCore;
    }
    
    function setFees(
        uint256 _depositFee,
        uint256 _withdrawFee,
        uint256 _performanceFee
    ) external onlyOwner {
        require(_depositFee <= 500, "Deposit fee too high");      // 最高5%
        require(_withdrawFee <= 500, "Withdraw fee too high");    // 最高5%
        require(_performanceFee <= 5000, "Performance fee too high"); // 最高50%
        
        depositFee = _depositFee;
        withdrawFee = _withdrawFee;
        performanceFee = _performanceFee;
    }
    
    function setLimits(
        uint256 _maxTotalAssets,
        uint256 _minDepositAmount
    ) external onlyOwner {
        maxTotalAssets = _maxTotalAssets;
        minDepositAmount = _minDepositAmount;
    }
    
    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
    }
    
    /**
     * @dev 紧急提取（仅owner，仅限紧急情况）
     */
    function emergencyWithdraw(address token) external onlyOwner {
        if (token == address(asset)) {
            // 只能提取超出用户份额的部分
            revert("Cannot withdraw user assets");
        }
        
        uint256 balance = IERC20(token).balanceOf(address(this));
        IERC20(token).safeTransfer(owner(), balance);
    }
}

contracts/core/ConfigManage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IConfigManager.sol";

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

/**
 * 参数配置合约
 * 用于管理套利策略的参数配置
 * 包括：
 * - 关键合约地址配置
 * - 手续费配置
 * - 滑点设置
 */
contract ConfigManage is IConfigManager, Initializable, OwnableUpgradeable, UUPSUpgradeable {

    uint16 public version;
    uint256 private _profitShareFee;

    // 可配置的费用参数
    uint256 public depositFee = 0;              // 存款费（basis points）
    uint256 public withdrawFee = 1;             // 提款费（basis points） 暂定0.01%
    uint256 public performanceFee = 1000;       // 业绩费（basis points） 暂定10%

    // 滑点容忍度（basis points）
    uint256 public slippageTolerance;

        address public lendingPool;
    address public uniswapV2Router;
    address public uniswapV3Router;
    address public sushiSwapRouter;
    address public arbitrageVault;

    event Upgrade(address indexed implemetation, uint256 version);
    event DepositFeeUpdated(uint256 newFee);
    event WithdrawFeeUpdated(uint256 newFee);
    event PerformanceFeeUpdated(uint256 newFee);
    
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _lendingPool,
        address _uniswapV2Router,
        address _uniswapV3Router,
        address _sushiSwapRouter,
        address _arbitrageVault
    ) public initializer {
        __Ownable_init(msg.sender);
        __UUPSUpgradeable_init();

        require(_lendingPool != address(0), "Invalid lending pool");
        require(_uniswapV2Router != address(0), "Invalid uniswapV2 router");
        require(_uniswapV3Router != address(0), "Invalid uniswapV3 router");
        require(_sushiSwapRouter != address(0), "Invalid sushiSwap router");

        lendingPool = _lendingPool;
        uniswapV2Router = _uniswapV2Router;
        uniswapV3Router = _uniswapV3Router;
        sushiSwapRouter = _sushiSwapRouter;
        arbitrageVault = _arbitrageVault;
        version = 1;
        // 默认滑点500（5%）
        slippageTolerance = 500;
    }

    //ArbitrageCore合约用到平台分成
    function profitShareFee() external view override returns(uint256) {
        return _profitShareFee;
    }

    //管理员可对平台分成进行配置
    function setProfitShareFee(uint256 feeBps) external onlyOwner {
        require(feeBps < 10000, "feeBps too high");
        _profitShareFee = feeBps;
    }

    // ========== 可插拔费用配置 ==========
    
    /**
     * @dev 设置存款费
     * @param _depositFee 新的存款费（basis points，如100表示1%）
     */
    function setDepositFee(uint256 _depositFee) external onlyOwner {
        require(_depositFee <= 10000, "Fee too high");
        depositFee = _depositFee;
        emit DepositFeeUpdated(_depositFee);
    }

    /**
     * @dev 设置提款费
     * @param _withdrawFee 新的提款费（basis points，如100表示1%）
     */
    function setWithdrawFee(uint256 _withdrawFee) external onlyOwner {
        require(_withdrawFee <= 10000, "Fee too high");
        withdrawFee = _withdrawFee;
        emit WithdrawFeeUpdated(_withdrawFee);
    }

    /**
     * @dev 设置业绩费
     * @param _performanceFee 新的业绩费（basis points，如1000表示10%）
     */
    function setPerformanceFee(uint256 _performanceFee) external onlyOwner {
        require(_performanceFee <= 10000, "Fee too high");
        performanceFee = _performanceFee;
        emit PerformanceFeeUpdated(_performanceFee);
    }

    /**
     * @dev 批量设置所有费用
     */
    function setAllFees(
        uint256 _depositFee,
        uint256 _withdrawFee,
        uint256 _performanceFee
    ) external onlyOwner {
        require(_depositFee <= 10000, "Deposit fee too high");
        require(_withdrawFee <= 10000, "Withdraw fee too high");
        require(_performanceFee <= 10000, "Performance fee too high");
        
        depositFee = _depositFee;
        withdrawFee = _withdrawFee;
        performanceFee = _performanceFee;
        
        emit DepositFeeUpdated(_depositFee);
        emit WithdrawFeeUpdated(_withdrawFee);
        emit PerformanceFeeUpdated(_performanceFee);
    }

    function getDepositFee(address /* vault */) external view override returns(uint256) {
        return depositFee;
    }

    function getWithDrawFee(address /* vault */) external view override returns(uint256) {
        return withdrawFee;
    }

    function getPlatFormFee(address /* vault */) external view override returns(uint256) {
        return performanceFee;
    }

    /**
     * 动态配置滑点
     * 请求参数：
     *      _slipageTolerance：滑点容忍度
     */
    function setSlipageTolerance(uint _slippageTolerance) external onlyOwner{
        slippageTolerance = _slippageTolerance;
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner{
        require(newImplementation != address(0), "New implementation is zero address");
        version ++;
        emit Upgrade(newImplementation, version);
    }

}

contracts/core/FlashLoanArbitrage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IFlashLoan.sol";
import "../router/FlashLoanRouter.sol";
import "../interfaces/ISpotArbitrage.sol";

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract FlashLoanArbitrage is IFlashLoanSimpleReceiver, ReentrancyGuard, Ownable  {
    /**
    *功能：集成Aave闪电贷
    *闪电贷回调
    *利润计算
    *自动还款
    *本合约为闪电贷套利工作流管理，
    *本合约调用实现合约SpotArbitrage实施套利动作
    *本合约被ArbitrageCore调用
    */

    //定义变量，借贷池，借贷平台等
    FlashLoanRouter public immutable flashLoan;     //路由合约
    ISpotArbitrage public immutable SpotArbitrage;  //套利实现合约接口
    address public arbitrageCore;                   // 核心调度合约

    //项目平台手续费
    uint256 public constant PROFIT_SHARE_FEE = 1000;//平台收取利润的10%作为服务费

    //当前执行上下文，用于回调时获取参数
    struct ExcutionContext {
        address initiator;  //发起人
        address tokenIn;    //初始代币
        uint256 amountIn;   //借款额度（申请金额）
        address[] swapPath; //策略路径
        address[] dexes;    //dex路径
        uint256 minProfit;  //最小利润
        bool isExcuting;     //正在执行标识
    }

    ExcutionContext private currentContext;

    //执行记录
    struct ExcutionRecord {
        address initiator;  
        address tokenIn;    
        uint256 amountIn; 
        uint256 profit;
        uint256 timestamp;
    }
 
    ExcutionRecord[] public excutedHistory; 

    //定义事件，进行记录等
    event FlashLoanRequest(
        address indexed initiator,
        address indexed token,
        uint256 amount,
        FlashLoanRouter.LendingPlatForm platForm
    );

    event FlashLoanExcuted(
        address indexed initiator,
        address indexed token,
        uint256 borrowed, //实际借款
        uint256 premium,  //平台利息
        uint256 profit    //最后利润 
    );

    event FlashLoanFaild(
        address indexed initiator,
        string reason
    );

    //修饰器

    modifier onlyArbgitrageCore(){
        require(msg.sender == arbitrageCore, "only ArbgitrageCore can call ");
        _;
    }

    modifier notExcuting() {
        require(!currentContext.isExcuting, "It's excuting");
        _;
    }

    //初始化构造函数
    //lendingPoolAddressProvider:借贷池地址提供者
    constructor (
        address _flashLoanRouter,
        address _spotArbitrage,
        address _arbitrageCore
    ) Ownable(msg.sender) {
        require(_flashLoanRouter != address(0), "Invalid flashLoanRouter");
        require(_spotArbitrage != address(0), "Invalid spotArbitrage");
        require(_arbitrageCore != address(0), "Invalid arbitrageCore");

        flashLoan = FlashLoanRouter(_flashLoanRouter);
        SpotArbitrage = ISpotArbitrage(_spotArbitrage);
        arbitrageCore = _arbitrageCore;
    }

    //闪电贷回调函数
    function executeOperation(
        address asset,
        uint256 amount,
        uint256 premium,
        address initiator,
        bytes calldata params
    ) external override returns (bool) {
        //解码参数
        (
            address _initiator,
            address tokenIn,
            uint256 amountIn,
            address[] memory swapPath,
            address[] memory dexes,
            uint256 minProfit
        ) = abi.decode(
            params,
            (address, address, uint256, address[], address[], uint256)
        );

        require(_initiator == initiator, "Invalid initiator");

        //实施套利
        uint256 amountOut = SpotArbitrage.executeSwaps(
            asset,
            swapPath[swapPath.length - 1],
            amountIn,
            swapPath,
            dexes,
            minProfit
        );

        //计算利润
        uint256 totalDebt = amount + premium;
        require(amountOut > totalDebt + minProfit, "No profit made");

        uint256 profit = amountOut - totalDebt;

        //支付闪电贷
        IERC20(asset).approve(address(flashLoan), totalDebt);

        //记录执行历史
        excutedHistory.push(ExcutionRecord({
            initiator: initiator,
            tokenIn: tokenIn,
            amountIn: amountIn,
            profit: profit,
            timestamp: block.timestamp
        }));

        emit FlashLoanExcuted(
            initiator,
            asset,
            amount,
            premium,
            profit
        );

        return true;
    }

    //核心函数：实施闪电贷，并调用内部函数_initFlashLoan发起闪电贷
    function executeFlashLoan(
        FlashLoanRouter.LendingPlatForm platform,
        address tokenIn,
        uint256 amountIn,
        address[] calldata swapPath,
        address[] calldata dexes,
        uint256 minProfit
    ) external onlyArbgitrageCore notExcuting {
        //设置当前执行上下文
        currentContext = ExcutionContext({
            initiator: msg.sender,
            tokenIn: tokenIn,
            amountIn: amountIn,
            swapPath: swapPath,
            dexes: dexes,
            minProfit: minProfit,
            isExcuting: true
        });

        //发起闪电贷
        _initFlashLoan(platform, tokenIn, amountIn);

        //清理当前执行上下文
        delete currentContext;
    }
    //内部函数_initFlashLoan，选择闪电贷平台（如AAVE），调用内部函数_initAAVEFlashLoan进行闪电贷
    function _initFlashLoan(
        FlashLoanRouter.LendingPlatForm platform,
        address asset,
        uint256 amount
    ) internal {
        //构造参数
        bytes memory params = abi.encode(
            currentContext.initiator,
            currentContext.tokenIn,
            currentContext.amountIn,
            currentContext.swapPath,
            currentContext.dexes,
            currentContext.minProfit
        );

        //发起闪电贷
        flashLoan.requsetFlashLoan(
            platform,
            address(this),
            asset,
            amount,
            params
        );

        emit FlashLoanRequest(
            currentContext.initiator,
            asset,
            amount,
            platform
        );
    }
    //内部函数_initAAVEFlashLoan,发起AAVE闪电贷
    function _initAAVEFlashLoan(
        address asset,
        uint256 amount,
        bytes memory params
    ) internal {
        //调用Aave闪电贷路由合约
        flashLoan.requsetFlashLoan(
            FlashLoanRouter.LendingPlatForm.Aave_V2,
            address(this),
            asset,
            amount,
            params
        );
    }
    //内部函数_initDYDXFlashLoan,发起DYDX闪电贷(扩展)


}

