// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/ISpotArbitrage.sol";
import "../interfaces/IDoubleRouterIntegration.sol";
import "../interfaces/IUniswapV2Integration.sol";



contract SpotArbitrage is ISpotArbitrage{

    IDoubleRouterIntegration private doubleRouterIntegration;
    IUniswapV2Integration private uniswapV2Integration;

    constructor(address _doubleRouterIntegration, address _uniswapV2Integration) {
        doubleRouterIntegration = IDoubleRouterIntegration(_doubleRouterIntegration);
        uniswapV2Integration = IUniswapV2Integration(_uniswapV2Integration);
    }

    /**
    *实施AMM-AMM套利的实现合约
    *对后端提供的策略（包含代币转换路径和交易所）循环遍历并进行swap
    *
    *
    *
    *本合约被ArbitrageCore调用
    */
    function executeSwaps(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        address[] calldata swapPath,
        address[] calldata dexes,
        uint256 /* minProfit */
    ) external returns(uint256 amountOut) {
        // minProfit parameter is part of the ISpotArbitrage interface for checks at higher level;
        // this implementation delegates swaps to doubleRouterIntegration and ignores minProfit here.
        return doubleRouterIntegration.doubleRouterSwap2(address(this), tokenIn, tokenOut, amountIn, swapPath, dexes);
    }
}

contracts/integrations/DoubleRouterInteg.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../core/ConfigManage.sol";
import "../interfaces/IUniswapV2Router02.sol";
import "../interfaces/IDoubleRouterIntegration.sol";

import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

contract DoubleRouterIntegration is IDoubleRouterIntegration {

    using SafeERC20 for IERC20;

    // address vault = ConfigManage.arbitrageVault;
    ConfigManage public configManage;
    uint256 public slippageTolerance;
    address public admin;

    constructor(address _configManage) {
        admin = msg.sender;
        configManage = ConfigManage(_configManage);
        slippageTolerance = configManage.slippageTolerance();
    }

    event DoubleRouterSwap(
        address indexed sender, 
        address indexed routerA, 
        address indexed routerB, 
        uint256 amountIn, 
        uint256 profit
    );

    event DoubleRouterSwap2(
        address indexed routerAddr, 
        address indexed fromToken, 
        address indexed toToken, 
        uint256 currentAmount, 
        uint256 outAmount
    );

    /**
     * 多路由验证路径是否可获利
     * 请求参数：
     *      amountIn：交易数量
     *      path：交易路径
     *           [A, B, C, A]
     *      routers：路由
     *           每跳的 router，如 [uni, sushi, uni]
     * 返回参数：
     *      profitable: 是否可获利
     *      finalAmount：返回数量
     *      profit：利润（负数表示亏损）
     */
    function doubleRouterArbCheck(
        uint amountIn,
        address[] calldata path,
        address[] calldata routers
    ) external view returns(
        bool profitable,
        uint finalAmount,
        int profit
    ) {
        require(path.length >= 2, "Invalid path");
        require(path[0] == path[path.length - 1], "Must return to start");
        require(routers.length == path.length - 1, "Router count mismatch");

        uint256 currentAmount = amountIn;

        for (uint i = 0; i < routers.length; i++) {
            address router = routers[i];
            address from = path[i];
            address to = path[i + 1];

            address[] memory stepPath;
            stepPath[0] = from;
            stepPath[1] = to;

            IUniswapV2Router02 swapRouter = IUniswapV2Router02(router);

            uint256[] memory amounts;
            try swapRouter.getAmountsOut(currentAmount, stepPath) returns (uint256[] memory result) {
                amounts = result;
            } catch {
                // 任意跳失败 = 套利不成立
                return (false, 0, -1);
            }

            currentAmount = amounts[1];
        }

        uint finalOut = currentAmount;

        bool isProfit = finalOut > amountIn;
        int profitAmount = int(finalOut) - int(amountIn);

        return (isProfit, finalOut, profitAmount);
    }


    /**
     * 双路由交易
     * @param routerA routerA地址
     * @param routerB routerB地址
     * @param amountIn 交易数量
     * @param pathA 交易路径A
     * @param pathB 交易路径B
     * @param minProfit 最小利润
     */    
    function doubleRouterSwap(
        address routerA,
        address routerB,
        uint256 amountIn,
        address[] calldata pathA,
        address[] calldata pathB,
        uint256 minProfit
    ) external {
    
        require(pathA.length >= 2 && pathB.length >= 2, "invalid path");
        require(amountIn > 0, "zero amount");
        require(pathB[0] == pathA[pathA.length - 1], "pathB start mismatch");
        require(pathB[pathB.length - 1] == pathA[0], "pathB end mismatch");
        require(IERC20(pathA[0]).balanceOf(address(this)) >= amountIn, "insufficient balance");

        uint256 deadline = block.timestamp + 300;
        address tokenA = pathA[0];
        address tokenB = pathA[pathA.length - 1];

        // Step 1: 调用子函数完成 RouterA 兑换
        _swapOnRouter(routerA, tokenA, amountIn, pathA, deadline);
        
        // 校验 tokenB 余额
        require(IERC20(tokenB).balanceOf(address(this)) > 0, "no tokenB received");
        
        // Step 2: 调用子函数完成 RouterB 兑换
        uint256 tokenBBalance = IERC20(tokenB).balanceOf(address(this));
        _swapOnRouter(routerB, tokenB, tokenBBalance, pathB, deadline);

        // 利润校验
        uint256 endBalance = IERC20(tokenA).balanceOf(address(this));
        uint256 profit = endBalance - (IERC20(tokenA).balanceOf(address(this)) - amountIn);
        require(profit > 0 && profit >= minProfit, "insufficient profit");

        emit DoubleRouterSwap(msg.sender, routerA, routerB, amountIn, profit);
    }

    function _swapOnRouter(
        address router,
        address tokenIn,
        uint256 amountIn,
        address[] calldata path,
        uint256 deadline
    ) internal {
        uint256 expectedOut = IUniswapV2Router02(router).getAmountsOut(amountIn, path)[path.length - 1];
        uint256 amountOutMin = (expectedOut * (10000 - slippageTolerance)) / 10000;

        IERC20(tokenIn).approve(router, amountIn);
        IUniswapV2Router02(router).swapExactTokensForTokensSupportingFeeOnTransferTokens(
            amountIn, amountOutMin, path, address(this), deadline
        );
    }

    function doubleRouterSwap2(
        address spot,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        address[] calldata swapPath,
        address[] calldata dexes
    ) external returns(uint256 amountOut) {
        require(swapPath.length >= 2, "invalid swapPath");
        require(dexes.length == swapPath.length - 1, "dexes length mismatch");
        require(swapPath[swapPath.length - 1] == tokenOut, "tokenOut mismatch with swapPath");
        require(IERC20(tokenIn).balanceOf(spot) >= amountIn, "insufficient tokenIn balance");

        uint256 currentAmount = amountIn;
        uint256 deadline = block.timestamp + 300;

        for (uint i = 0; i < dexes.length; i++) {
            currentAmount = _executeSingleSwap(
                spot,
                dexes[i],
                swapPath[i],
                swapPath[i + 1],
                currentAmount,
                deadline
            );
        }
        amountOut = currentAmount;
    }

    function _executeSingleSwap(
        address spot,
        address routerAddr,
        address fromToken,
        address toToken,
        uint256 currentAmount,
        uint256 deadline
    ) internal returns (uint256 outAmount) {
        // 余额校验
        require(IERC20(fromToken).balanceOf(spot) >= currentAmount, "insufficient token balance for hop");

        // 授权
        IERC20(fromToken).approve(routerAddr, 0);
        IERC20(fromToken).approve(routerAddr, currentAmount);

        // 构建路径
        address[] memory path = new address[](2);
        path[0] = fromToken;
        path[1] = toToken;

        // 计算预期输出和最小输出
        uint256 expectedOut = IUniswapV2Router02(routerAddr).getAmountsOut(currentAmount, path)[1];
        uint256 minOut = (expectedOut * slippageTolerance) / 1000;
        minOut = minOut == 0 ? 1 : minOut;

        // 执行兑换
        outAmount = IUniswapV2Router02(routerAddr).swapExactTokensForTokens(
            currentAmount,
            minOut,
            path,
            spot,
            deadline
        )[1];

        // 触发事件
        emit DoubleRouterSwap2(routerAddr, fromToken, toToken, currentAmount, outAmount);
    }                               

}

contracts/integrations/UniswapV2Integrat.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IUniswapV2Integration.sol";
import "../interfaces/IUniswapV2Router02.sol";
import "../core/ConfigManage.sol";

import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
* IUniswapV2Router02支持uniswap和sushuiswap
*/
contract UniswapV2Integration is IUniswapV2Integration {
    
    using SafeERC20 for IERC20;

    ConfigManage public configManage;
    uint public slippageTolerance;
    address public admin;

    constructor(address _configManage) {
        admin = msg.sender;
        configManage = ConfigManage(_configManage);
        slippageTolerance = configManage.slippageTolerance();
    }

    /**
     * 单路由验证路径是否可获利
     * 请求参数：
     *      router: dex地址
     *      amountIn：交易数量
     *      path：交易路径
     * 返回参数：
     *      profitable: 是否可获利
     *      finalAmount：返回数量
     *      profit：利润（负数表示亏损）
     */
    function routerArbCheck(
        address router,
        uint256 amountIn,
        address[] calldata path
    ) external view returns (
        bool profitable,
        uint256 finalAmount,
        int profit
    ) {
        require(path.length >= 2, "Invalid path");
        require(path[0] == path[path.length - 1], "Path must return to start");

        IUniswapV2Router02 swapRouter = IUniswapV2Router02(router);

        uint256[] memory amounts;

        // 计算整个路径的 amountsOut
        try swapRouter.getAmountsOut(amountIn, path) returns (uint256[] memory result) {
            amounts = result;
        } catch {
            // path 不存在、池子没流动性等情况
            return (false, 0, -1);
        }

        uint finalOut = amounts[amounts.length - 1];

        // 盈利条件：最终 A 数量 > 初始 A 数量
        bool isProfit = finalOut > amountIn;

        // 利润（signed integer）
        int profitAmount = int(finalOut) - int(amountIn);
        return (isProfit, finalOut, profitAmount);
    }   

    event SwapV2(
        address indexed router, 
        address indexed token0, 
        address indexed token1, 
        uint amountIn, 
        uint amountOut, 
        uint expectedOut, 
        uint256 slippageTolerance
    );

    event SwapV2Multi(
        address indexed router, 
        address[][] paths, 
        uint amountIn, 
        uint amountOut
    );

    /** 
     * 单路由单路径
     * 请求参数：
     *      router：dex地址
     *      token0：代币地址0
     *      token1：代币地址1
     *      amountIn：交易数量
     *      minProfit: 最小收益
     */
    function swapV2(
        address router,
        address token0,
        address token1,
        uint256 amountIn,
        uint256 minProfit
    ) external {

        require(amountIn > 0, "amountIn must be > 0");

        address[] memory path = _getSwapPath(router, token0, token1);
        require(path.length >= 2, "invalid path");
        require(path[0] == token0, "path start mismatch");
        require(path[path.length - 1] == token1, "path end mismatch");

        // ===== 余额校验 =====
        require(IERC20(token0).balanceOf(address(this)) >= amountIn, "insufficient balance");

        // ===== 授权校验 =====
        if (IERC20(token0).allowance(address(this), router) < amountIn) {
            IERC20(token0).approve(router, 0);
            IERC20(token0).approve(router, amountIn);
        }

        // ===== 获取预期输出 =====
        uint256 expectedOut = IUniswapV2Router02(router).getAmountsOut(amountIn, path)[path.length - 1];
        require(expectedOut > 0, "zero expectedOut");

        // ===== 滑点保护 =====
        uint256 amountOutMin = expectedOut * (10000 - slippageTolerance) / 10000;
        amountOutMin = amountOutMin > 0 ? amountOutMin : 1;

        // ===== 执行 swap =====
        uint256 endBalance = IUniswapV2Router02(router).swapExactTokensForTokens(
            amountIn,
            amountOutMin,
            path,
            address(this),
            block.timestamp + 60
        )[path.length - 1];

        // 利润校验
        require(endBalance - IERC20(token0).balanceOf(address(this)) >= minProfit, "profit < minProfit");

        emit SwapV2(router, token0, token1, amountIn, endBalance, expectedOut, slippageTolerance);
    }


    /**
     * 单路由多路径
     * 请求参数：
     *      router：dex地址
     *      paths：策略路径，支持多路径{USDT->DAI->WETH}
     *          path[0]:[USDT,DAI]
     *          path[1]:[DAI,WETH] 
     *      amountIn：交易数量
     *      minProfit: 最小收益
     */
    function swapV2Multi(
        address router,
        address[][] calldata paths,
        uint256 amountIn,
        uint256 minProfit
    ) external {

        require(paths.length > 0, "empty paths");
        require(amountIn > 0, "zero amount");

        // 获取初始余额
        address tokenA = paths[0][0];
        uint256 startBalance = IERC20(tokenA).balanceOf(address(this));
        require(startBalance >= amountIn, "insufficient balance");

        IUniswapV2Router02 swapRouter = IUniswapV2Router02(router);

        uint256 startAmount = amountIn;
        uint256 currentAmount = amountIn;

        for (uint256 i = 0; i < paths.length; i++) {
            address[] calldata path = paths[i];
            require(path.length >= 2, "invalid path");

            uint256[] memory amountsOut = swapRouter.getAmountsOut(currentAmount, path);
            uint256 expectedOut = amountsOut[amountsOut.length - 1];
            require(expectedOut > 0, "zero expected out");

            // 滑点保护
            uint256 amountOutMin = expectedOut * (10000 - slippageTolerance) / 10000;
            require(amountOutMin > 0, "slippage too high");

            uint256[] memory result = swapRouter.swapExactTokensForTokens(
                currentAmount,
                amountOutMin,
                path,
                address(this),
                block.timestamp
            );

            currentAmount = result[result.length - 1];
        }

        // 只在最终校验利润
        uint256 profit = currentAmount - startBalance;
        require(profit >= minProfit, "profit < minProfit");

        emit SwapV2Multi(router, paths, startAmount, currentAmount);
    }


    /**
     * Get the swap path
     */
    function _getSwapPath(address _swapRouter,address token0,address token1) internal pure returns (address[] memory path){
        IUniswapV2Router02 IUniswap = IUniswapV2Router02(_swapRouter);
        path = new address[](2);
        path[0] = token0 == address(0) ? IUniswap.WETH() : token0;
        path[1] = token1 == address(0) ? IUniswap.WETH() : token1;
    }
}

